+load(":rule.bzl", "sample_setting")
+
+toolchain_type(name = "toolchain_type")
+sample_setting(
+    name = "demo",
+    build_setting_default = True,
+)
+EOF
+  cat >> demo/rule.bzl <<EOF
+def _sample_impl(ctx):
+    info = ctx.toolchains["//:toolchain_type"]
+    if info:
